{"implementation": "def solve(case):
    lines = case.get('lines', [])
    trajectory = []
    valid = True
    error_line = None
    allowed = {'thought'}
    final_seen = False
    for i, line in enumerate(lines):
        if ':' not in line:
            valid = False
            error_line = i + 1
            break
        parts = line.split(': ', 1)
        if len(parts) != 2:
            valid = False
            error_line = i + 1
            break
        typ = parts[0].strip().lower()
        content = parts[1].strip()
        if typ not in ('thought', 'action', 'observation', 'final'):
            valid = False
            error_line = i + 1
            break
        if typ not in allowed:
            valid = False
            error_line = i + 1
            break
        if typ == 'final':
            if i != len(lines) - 1:
                valid = False
                error_line = i + 1
                break
            final_seen = True
            allowed.clear()
        else:
            if typ == 'thought':
                allowed = {'action', 'final'}
            elif typ == 'action':
                allowed = {'observation'}
            elif typ == 'observation':
                allowed = {'thought'}
        trajectory.append({'type': typ, 'content': content})
    if not lines:
        valid = False
        error_line = 1
        trajectory = []
    elif valid and not final_seen:
        # last line should have been final; treat it as violation
        if trajectory:
            trajectory.pop()
        valid = False
        error_line = len(lines)
    return {'valid': valid, 'error_line': error_line, 'trajectory': trajectory}
"}
